type roleJoins[Q dialect.Joinable] struct {
	typ                 string
	Permissions         modAs[Q, permissionColumns]
	UserRoleAssignments modAs[Q, userRoleAssignmentColumns]
}

func (j roleJoins[Q]) aliasedAs(alias string) roleJoins[Q] {
	return buildRoleJoins[Q](buildRoleColumns(alias), j.typ)
}

func buildRoleJoins[Q dialect.Joinable](cols roleColumns, typ string) roleJoins[Q] {
	return roleJoins[Q]{
		typ: typ,
		Permissions: modAs[Q, permissionColumns]{
			c: Permissions.Columns,
			f: func(to permissionColumns) bob.Mod[Q] {
				uniqueSuffix := strconv.FormatUint(bob.NextUniqueInt(), 10)
				mods := make(mods.QueryMods[Q], 0, 2)

				{
					to := RolePermissions.Columns.AliasedAs(RolePermissions.Columns.Alias() + uniqueSuffix)
					mods = append(mods, dialect.Join[Q](typ, RolePermissions.NameExpr().As(to.Alias())).On(
						to.RoleID.EQ(cols.ID),
					))
				}
				{
					cols := RolePermissions.Columns.AliasedAs(RolePermissions.Columns.Alias() + uniqueSuffix)
					mods = append(mods, dialect.Join[Q](typ, Permissions.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.PermissionID),
					))
				}

				return mods
			},
		},
		UserRoleAssignments: modAs[Q, userRoleAssignmentColumns]{
			c: UserRoleAssignments.Columns,
			f: func(to userRoleAssignmentColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, UserRoleAssignments.NameExpr().As(to.Alias())).On(
						to.RoleID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
